/**
 * The types `save/guardians/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    GuardianChipSaveRow, GuardianEquippedChipRow, GuardianSkinSaveRow, GuardiansSaveExtract
 * depends    —
 * used by    src/save/guardians/index, src/save/guardians/read
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from read.ts

export interface GuardianChipSaveRow {
  slotIndex: number
  chipType: string | null
  targetKey: string | null
  label: string
  unlocked: boolean
  statLevels: number[]
  equippedSlot: number | null
}

export interface GuardianEquippedChipRow {
  equipSlot: number
  slotIndex: number
  label: string
  targetKey: string | null
  statLevels: number[]
}

export interface GuardianSkinSaveRow {
  index: number
  label: string
  unlocked: boolean
  selected: boolean
}

export interface GuardiansSaveExtract {
  guardianUnlocked: boolean
  chips: GuardianChipSaveRow[]
  equippedChips: GuardianEquippedChipRow[]
  skins: GuardianSkinSaveRow[]
  slotsUnlocked: number | null
  skinIndex: number | null
  totalDamage: unknown
  totalCoins: unknown
  totalCatches: unknown
  warnings: string[]
}
